import React, { useState, useEffect } from "react";
import { BrowserRouter as Router, Route, Routes, Link, Navigate } from "react-router-dom";
import "./styles.css";

// Notification Component
const Notification = ({ message, onClose }) => {
  useEffect(() => {
    const timer = setTimeout(() => {
      onClose();
    }, 2000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return <div className="notification">{message}</div>;
};

// Home Page Component
const HomePage = () => {
  return (
    <div className="homePage">
      <h1 className="heading">Welcome to Binance Clone</h1>
      <Link to="/login">
        <button className="button">Get Started</button>
      </Link>
    </div>
  );
};

// Login Page Component
const LoginPage = ({ onLogin }) => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  const handleLogin = () => {
    if (!email || !password) {
      setError("Please fill in all fields.");
      return;
    }
    // Simulate a successful login
    onLogin();
  };

  return (
    <div className="loginPage">
      <h2 className="heading">Login</h2>
      {error && <div className="error">{error}</div>}
      <input
        type="email"
        placeholder="Email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        className="input"
      />
      <input
        type="password"
        placeholder="Password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        className="input"
      />
      <button onClick={handleLogin} className="button">
        Login
      </button>
      <p className="linkText">
        <Link to="/forgot-password" className="link">
          Forgot Password?
        </Link>
      </p>
      <p className="linkText">
        Don't have an account?{" "}
        <Link to="/signup" className="link">
          Sign Up
        </Link>
      </p>
    </div>
  );
};

// Forgot Password Page Component
const ForgotPasswordPage = () => {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const handleSubmit = () => {
    if (!email) {
      setError("Please enter your email.");
      return;
    }
    // Simulate sending a recovery link
    setSuccess("A recovery link has been sent to your email.");
    setError("");
  };

  return (
    <div className="forgotPasswordPage">
      <h2 className="heading">Trouble logging in?</h2>
      <p>Enter your email, and we'll send you a link to get back into your account.</p>
      {error && <div className="error">{error}</div>}
      {success && <div className="success">{success}</div>}
      <input
        type="email"
        placeholder="Email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        className="input"
      />
      <button onClick={handleSubmit} className="button">
        Send Recovery Link
      </button>
      <p className="linkText">
        <Link to="/login" className="link">
          Back to Login
        </Link>
      </p>
    </div>
  );
};

// Signup Page Component
const SignupPage = ({ onSignup }) => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [phone, setPhone] = useState("");
  const [error, setError] = useState("");

  const handleSignup = () => {
    if (!email || !password || !phone) {
      setError("Please fill in all fields.");
      return;
    }

    // Validate password (minimum 8 characters)
    if (password.length < 8) {
      setError("Password must be at least 8 characters long.");
      return;
    }

    // Validate phone number (Pakistani format: +92XXXXXXXXX)
    const phoneRegex = /^\+92\d{9}$/;
    if (!phoneRegex.test(phone)) {
      setError("Invalid phone number. Please use the format +92XXXXXXXXX.");
      return;
    }

    // Simulate signup logic
    onSignup({ email, password, phone });
  };

  return (
    <div className="signupPage">
      <h2 className="heading">Sign Up</h2>
      {error && <div className="error">{error}</div>}
      <input
        type="email"
        placeholder="Email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        className="input"
      />
      <input
        type="password"
        placeholder="Password (min 8 characters)"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        className="input"
      />
      <input
        type="text"
        placeholder="Phone Number (+92XXXXXXXXX)"
        value={phone}
        onChange={(e) => setPhone(e.target.value)}
        className="input"
      />
      <button onClick={handleSignup} className="button">
        Sign Up
      </button>
      <p className="linkText">
        Already have an account?{" "}
        <Link to="/login" className="link">
          Login
        </Link>
      </p>
    </div>
  );
};

// KYC Form Component
const KYCForm = ({ onKYCSubmit }) => {
  const [name, setName] = useState("");
  const [picture, setPicture] = useState(null);
  const [error, setError] = useState("");

  const handleSubmit = () => {
    if (!name || !picture) {
      setError("Please fill in all fields.");
      return;
    }

    // Validate name (alphabets only)
    const nameRegex = /^[A-Za-z\s]+$/;
    if (!nameRegex.test(name)) {
      setError("Name should contain only alphabets.");
      return;
    }

    // Validate picture (JPG/PNG, max size 2MB)
    if (picture.size > 2 * 1024 * 1024) {
      setError("Picture size should not exceed 2MB.");
      return;
    }

    onKYCSubmit({ name, picture });
  };

  return (
    <div className="kycPage">
      <h2 className="heading">KYC Verification</h2>
      {error && <div className="error">{error}</div>}
      <input
        type="text"
        placeholder="Full Name"
        value={name}
        onChange={(e) => setName(e.target.value)}
        className="input"
      />
      <input
        type="file"
        accept=".jpg,.png"
        onChange={(e) => setPicture(e.target.files[0])}
        className="input"
      />
      <button onClick={handleSubmit} className="button">
        Submit
      </button>
    </div>
  );
};

// Admin Panel Component
const AdminPanel = ({ kycRequests, onApprove, onRevoke, onAddNote }) => {
  const [notes, setNotes] = useState({});

  const handleAddNote = (index, note) => {
    setNotes({ ...notes, [index]: note });
    onAddNote(index, note);
  };

  return (
    <div className="adminPanel">
      <h2 className="heading">Admin Panel - KYC Requests</h2>
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Picture</th>
            <th>Status</th>
            <th>Actions</th>
            <th>Notes</th>
          </tr>
        </thead>
        <tbody>
          {kycRequests.map((request, index) => (
            <tr key={index}>
              <td>{request.name}</td>
              <td>
                <img
                  src={URL.createObjectURL(request.picture)}
                  alt="User"
                  style={{ width: "50px", height: "50px" }}
                />
              </td>
              <td>{request.status}</td>
              <td>
                <button onClick={() => onApprove(index)} className="button">
                  Approve
                </button>
                <button onClick={() => onRevoke(index)} className="button">
                  Revoke
                </button>
              </td>
              <td>
                <input
                  type="text"
                  placeholder="Add a note"
                  value={notes[index] || ""}
                  onChange={(e) => handleAddNote(index, e.target.value)}
                  className="input"
                />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

// Dashboard Component
const Dashboard = ({ user, kycStatus, accountStatus }) => {
  return (
    <div className="dashboard">
      <h2 className="heading">Dashboard</h2>
      {accountStatus === "blocked" && (
        <div className="blockedBanner">
          Your account is blocked. Contact support.
        </div>
      )}
      <div className="status">
        <h3>Account Status: {accountStatus}</h3>
        <h3>KYC Status: {kycStatus}</h3>
      </div>
    </div>
  );
};

// App Component
const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isKYCSubmitted, setIsKYCSubmitted] = useState(false);
  const [user, setUser] = useState(null);
  const [kycRequests, setKycRequests] = useState([]);
  const [kycStatus, setKycStatus] = useState("Pending");
  const [accountStatus, setAccountStatus] = useState("pending");
  const [notification, setNotification] = useState("");

  const handleLogin = () => {
    setIsLoggedIn(true);
  };

  const handleSignup = (userData) => {
    setUser(userData);
    setIsLoggedIn(true);
  };

  const handleKYCSubmit = (kycData) => {
    setKycRequests([...kycRequests, { ...kycData, status: "Pending" }]);
    setIsKYCSubmitted(true);
    setNotification("KYC submitted successfully!");
  };

  const handleApprove = (index) => {
    const updatedRequests = [...kycRequests];
    updatedRequests[index].status = "Approved";
    setKycRequests(updatedRequests);
    setKycStatus("Approved");
    setAccountStatus("active");
    setNotification("KYC approved! You can now perform transactions.");
  };

  const handleRevoke = (index) => {
    const updatedRequests = [...kycRequests];
    updatedRequests[index].status = "Revoked";
    setKycRequests(updatedRequests);
    setKycStatus("Revoked");
    setAccountStatus("blocked");
    setNotification("KYC revoked. Please re-submit your documents.");
  };

  const handleAddNote = (index, note) => {
    const updatedRequests = [...kycRequests];
    updatedRequests[index].note = note;
    setKycRequests(updatedRequests);
  };

  return (
    <Router>
      <div className="app">
        {notification && (
          <Notification
            message={notification}
            onClose={() => setNotification("")}
          />
        )}
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route
            path="/login"
            element={
              isLoggedIn ? (
                <Navigate to="/kyc" />
              ) : (
                <LoginPage onLogin={handleLogin} />
              )
            }
          />
          <Route
            path="/forgot-password"
            element={<ForgotPasswordPage />}
          />
          <Route
            path="/signup"
            element={<SignupPage onSignup={handleSignup} />}
          />
          <Route
            path="/kyc"
            element={
              isKYCSubmitted ? (
                <Navigate to="/dashboard" />
              ) : isLoggedIn ? (
                <KYCForm onKYCSubmit={handleKYCSubmit} />
              ) : (
                <Navigate to="/login" />
              )
            }
          />
          <Route
            path="/dashboard"
            element={
              isKYCSubmitted ? (
                <Dashboard
                  user={user}
                  kycStatus={kycStatus}
                  accountStatus={accountStatus}
                />
              ) : (
                <Navigate to="/login" />
              )
            }
          />
          <Route
            path="/admin"
            element={
              <AdminPanel
                kycRequests={kycRequests}
                onApprove={handleApprove}
                onRevoke={handleRevoke}
                onAddNote={handleAddNote}
              />
            }
          />
        </Routes>
      </div>
    </Router>
  );
};

export default App;
